#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    if (argc > 14) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    int coeff_cnt = argc - 2;
    if (coeff_cnt > 1000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    char *endptr;
    long long x = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long long coeffs[1000];
    for (int i = 0; i < coeff_cnt; ++i) {
        long long v = strtoll(argv[2 + i], &endptr, 10);
        if (*endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        coeffs[i] = v;
    }
    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeffs[i];
    }
    printf("%lld\n", result);
    return 0;
}
